<?php
declare(strict_types=1);namespace App\Imperium\Runtime\Foundry;use App\Bootstrap\CanonicalJson;use Symfony\Component\DependencyInjection\Attribute\Autowire;
final readonly class SubordinatePersonaSpecificationService{private string $caseDirectory;private string $specificationDirectory;public function __construct(#[Autowire('%kernel.project_dir%')]string $projectDir,private SubordinatePersonaSpecificationCognitionGateway $cognition){$this->caseDirectory=$projectDir.'/var/imperium/offices/foundry/subordinate-construction-cases';$this->specificationDirectory=$projectDir.'/var/imperium/offices/foundry/subordinate-persona-specifications';}public function specify(string $caseId):array{if(!preg_match('/^subordinate-construction-case-[a-f0-9]{20}$/',$caseId))throw new \InvalidArgumentException('F110_SUBORDINATE_CASE_ID_INVALID');$case=$this->read($this->caseDirectory.'/'.$caseId.'.json','F111_SUBORDINATE_CASE_ABSENT');if(!$this->digestMatches($case)||'imperium.foundry-subordinate-construction-case/v1'!==($case['schema']??null)||$caseId!==($case['case_id']??null)||'OPEN_PENDING_PERSONA_SPECIFICATION'!==($case['status']??null)||true!==($case['construction_authority']??null)||true===($case['persona_selection_authority']??null)||true===($case['profile_approval_authority']??null)||true===($case['spawning_authority']??null)||true===($case['admission_authority']??null)||true===($case['seat_binding_authority']??null)||true===($case['execution_authority']??null)||!is_array($case['subordinate_requirements']??null))throw new \RuntimeException('F112_SUBORDINATE_CASE_INVALID');foreach(glob($this->specificationDirectory.'/subordinate-persona-specification-*.json')?:[]as$p){$old=$this->read($p,'F115_SPECIFICATION_REPLAY_CONFLICT');if($caseId===($old['case_id']??null)&&$this->digestMatches($old))return$old;}$decision=$this->cognition->specify($case);$complete='PERSONA_SPECIFICATION_COMPLETE'===($decision['disposition']??null);$id='subordinate-persona-specification-'.substr(hash('sha256',CanonicalJson::encode([$caseId,$case['record_digest'],$decision])),0,20);return$this->persist($id,['schema'=>'imperium.foundry-subordinate-persona-specification/v1','specification_id'=>$id,'instance_id'=>$case['instance_id'],'case_id'=>$caseId,'case_digest'=>$case['record_digest'],'queue_position'=>$case['queue_position'],'office'=>$case['office'],'subordinate_staff_class'=>$case['subordinate_staff_class'],'source_resolution_id'=>$case['source_resolution_id'],'source_resolution_digest'=>$case['source_resolution_digest'],'artificer'=>$case['artificer'],'inherited_requirements'=>$case['subordinate_requirements'],'specification'=>$decision,'status'=>$complete?'SEALED_PENDING_PERSONA_CONSTRUCTION':'CLARIFICATION_REQUIRED','persona_specification_complete'=>$complete,'construction_authority'=>$complete,'persona_selection_authority'=>false,'profile_approval_authority'=>false,'spawning_authority'=>false,'admission_authority'=>false,'seat_binding_authority'=>false,'execution_authority'=>false,'sealed'=>true]);}private function read(string$p,string$e):array{if(!is_file($p))throw new \RuntimeException($e);return json_decode((string)file_get_contents($p),true,512,JSON_THROW_ON_ERROR);}private function digestMatches(array$r):bool{$d=$r['record_digest']??null;unset($r['record_digest']);return is_string($d)&&hash_equals($d,hash('sha256',CanonicalJson::encode($r)));}private function persist(string$id,array$r):array{if(!is_dir($this->specificationDirectory)&&!mkdir($this->specificationDirectory,0770,true)&&!is_dir($this->specificationDirectory))throw new \RuntimeException('Foundry subordinate Persona-specification directory cannot be created.');$r['record_digest']=hash('sha256',CanonicalJson::encode($r));$p=$this->specificationDirectory.'/'.$id.'.json';if(is_file($p)){$old=$this->read($p,'F115_SPECIFICATION_REPLAY_CONFLICT');if(CanonicalJson::encode($old)!==CanonicalJson::encode($r))throw new \RuntimeException('F115_SPECIFICATION_REPLAY_CONFLICT');return$old;}$tmp=$p.'.tmp.'.bin2hex(random_bytes(6));if(false===file_put_contents($tmp,json_encode($r,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR)."\n",LOCK_EX)||!rename($tmp,$p)){@unlink($tmp);throw new \RuntimeException('Persona specification cannot be committed atomically.');}return$r;}}
